                self.bob_history == other.bob_history and
                self.all_chosen == other.all_chosen and
                self.current_player == other.current_player)

    def get_valid_moves(self):
        moves = []

        is_alice_turn = self.current_player == 'Alice'

        if is_alice_turn:
            player_history = self.alice_history
        else:
            player_history = self.bob_history

        forbidden_by_history = set()
        for h in player_history:
            forbidden_by_history.add(h - 1)
            forbidden_by_history.add(h + 1)

        for k in range(1, self.n + 1):
            if k not in self.all_chosen:
                if k not in forbidden_by_history:
                    moves.append(k)

        return moves

